function renderVKids(lang) {
    const container = document.getElementById('vkids-list');
    
    // FIX: Try to get lang-specific data first, fallback to 'en'
    const items = vkidsData[lang] || vkidsData['en']; 

    if (!container) return;
    
    // FIX: Force the container to RTL if the language is Arabic
    if (lang === 'ar') {
        container.setAttribute('dir', 'rtl');
    } else {
        container.setAttribute('dir', 'ltr');
    }

    container.innerHTML = items.map(item => {
        // Use the lang passed to the function
        const title = item.title[lang] || item.title['en'];
        const desc = item.desc[lang] || item.desc['en'];
        const bannerSrc = item.banner[lang] || item.banner['en'];
        
        // Dynamically replace {{lang}} in the URL with the active language
        let dynamicLink = "#";
        if (item.link) {
            // Optional: If you want English to NOT have /en/ in the URL, you could use:
            // dynamicLink = lang === 'en' ? item.link.replace('/{{lang}}', '') : item.link.replace('{{lang}}', lang);
            
            // Standard replacement:
            dynamicLink = item.link.replace('{{lang}}', lang);
        }
        
        const watchText = (typeof translations !== 'undefined' && translations[lang] && translations[lang]['vkids.watch']) || 'WATCH VIDEO';
        const readText = (typeof translations !== 'undefined' && translations[lang] && translations[lang]['vkids.read']) || 'READ ARTICLE';

        return `
            <div class="vkids-card">
                <div class="vkids-banner">
                    <img src="${bannerSrc}" alt="${title}">
                </div>
                <div class="vkids-content">
                    <h3>${title}</h3>
                    <p>${desc}</p>
                    <div class="vkids-actions">
                        ${item.type === 'video' 
                            ? `<button class="v-btn-gold" onclick="launchVKidsVideo('${item.videoId}')">▶ ${watchText}</button>`
                            : `<a href="${dynamicLink}" class="v-btn-gold" target="_blank">📖 ${readText}</a>`
                        }
                    </div>
                </div>
            </div>
        `;
    }).join('');
}

window.launchVKidsVideo = function(id) {
    const modal = document.getElementById('videoModal');
    
    // 1. Show the modal first (flex helps center the content)
    if (modal) {
        modal.style.display = 'flex';
    }

    // 2. Get the player instance
    const myPlayer = videojs.getPlayer('vkidsBrightcovePlayer');
    
    if (myPlayer) {
        // Clear any old tracks/sources to prevent errors
        myPlayer.pause();
        myPlayer.src([]);

        myPlayer.catalog.getVideo(id, function(error, video) {
            if (error) {
                console.error("Brightcove Catalog Error:", error);
                return;
            }

            myPlayer.catalog.load(video);
            
            myPlayer.ready(function() {
                myPlayer.play().catch(e => console.warn("Autoplay blocked"));
                myPlayer.trigger('resize');
            });
        });
    }
};

window.closeVideoModalVKids = function() {
    const modal = document.getElementById('videoModal');
    const myPlayer = videojs.getPlayer('vkidsBrightcovePlayer');
    
    if (modal) {
        modal.style.display = 'none';
    }
    
    if (myPlayer) {
        myPlayer.pause();
    }
};

