document.addEventListener("DOMContentLoaded", () => {
    const grid = document.querySelector('.vkids-grid');

    if (!grid) return; // Failsafe in case the grid isn't on the page

    const updateFade = () => {
        const isRTL = getComputedStyle(grid).direction === 'rtl';
        
        // In RTL, scrollLeft is 0 at the start (right side) 
        // and becomes negative as you scroll.
        const scrollPos = Math.abs(grid.scrollLeft);

        if (scrollPos > 0) {
            grid.classList.add('not-at-start');
        } else {
            grid.classList.remove('not-at-start');
        }

        if (scrollPos + grid.clientWidth >= grid.scrollWidth - 1) {
            grid.classList.add('at-end');
        } else {
            grid.classList.remove('at-end');
        }
    };

    // Listen for scrolling and update the fades
    grid.addEventListener('scroll', updateFade);
    
    // Run it once right away just in case the content doesn't need to scroll
    updateFade();
});

// TICKET MENU
function toggleTicketMenu() {
    const hub = document.getElementById('ticketHub');
    const options = document.getElementById('ticketOptions');
    const backToTop = document.getElementById('backToTop');
    const isMobile = window.innerWidth <= 768;

    if (options.style.display === 'none' || options.style.display === '') {
        options.style.display = 'flex';
        hub.classList.add('stop-animation');
        
        // Slide it up even higher to clear the expanded menu
        if (backToTop) backToTop.style.bottom = isMobile ? "220px" : "250px";
    } else {
        options.style.display = 'none';
        hub.classList.remove('stop-animation');
        
        // Return to its "resting" position above the closed button
        if (backToTop) backToTop.style.bottom = isMobile ? "90px" : "110px";
    }
}

window.onscroll = function() {
    const backToTop = document.getElementById('backToTop');
    const hub = document.getElementById('ticketHub');
    const isMobile = window.innerWidth <= 768;
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;

    // Show/Hide Back to Top button based on distance from top
    if (scrollTop > 300) {
        backToTop.classList.add('visible');
    } else {
        backToTop.classList.remove('visible');
    }

    // Manual Scroll Resurrection (User scrolls up without clicking the button)
    if (scrollTop < 50 && hub && hub.style.display === 'none') {
        hub.style.display = 'flex';
        setTimeout(() => {
            hub.style.opacity = "1";
            hub.style.transform = "translateY(0) scale(1)";
            if (backToTop) backToTop.style.bottom = isMobile ? "90px" : "110px";
        }, 50);
    }
};

/* --- 3. DISMISS FUNCTION (Updated) --- */
function dismissEntireHub(event) {
    event.stopPropagation();
    const hub = document.getElementById('ticketHub');
    const backToTop = document.getElementById('backToTop');
    const isMobile = window.innerWidth <= 768;

    // Drop the Back to Top button to the corner
    if (backToTop) {
        backToTop.style.bottom = isMobile ? "20px" : "30px";
    }

    // Animation out
    hub.style.transition = "all 0.4s ease";
    hub.style.opacity = "0";
    hub.style.transform = "translateY(50px) scale(0)";
    
    // Crucial: Use display: 'none' so we can check for it later in the scroll function
    setTimeout(() => {
        hub.style.display = 'none';
    }, 400);
}

// This function handles the "Back to Top" click
function handleBackToTopClick(e) {
    // 1. Smooth scroll to the top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    const hub = document.getElementById('ticketHub');
    const backToTop = document.getElementById('backToTop');
    const isMobile = window.innerWidth <= 768;

    // 2. Resurrection Logic: If the CTA was closed, bring it back
    if (hub && hub.style.display === 'none') {
        // Prepare the hub for animation
        hub.style.display = 'flex';
        
        // We wait 400ms so the hub reappears AFTER the user has mostly finished scrolling up
        setTimeout(() => {
            hub.style.opacity = "1";
            hub.style.transform = "translateY(0) scale(1)";
            
            // Push the Back to Top button back to its "waiting" spot
            if (backToTop) {
                backToTop.style.bottom = isMobile ? "90px" : "110px";
            }
        }, 400); 
    }
}


// CHANGE LANGUAGE
function changeLanguage(lang) {
    localStorage.setItem('selectedLanguage', lang);
    
    const isRTL = (lang === 'ar');
    // This is the key that unlocks the CSS rules above
    document.documentElement.dir = isRTL ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;

    // 2. Update all static elements with data-i18n
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[lang] && translations[lang][key]) {
            el.innerHTML= translations[lang][key];
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(element => {
    const key = element.getAttribute('data-i18n-placeholder');
    if (translations[lang][key]) {
        element.placeholder = translations[lang][key];
    }

    if (typeof handleCategoryChange === 'function') {
    handleCategoryChange();
}

// This forces the static dropdowns (All Media, All Days) to translate
document.querySelectorAll('select option[data-i18n]').forEach(opt => {
    const key = opt.getAttribute('data-i18n');
    opt.innerHTML = getManualTranslation(key, opt.textContent);
});
});

    if (typeof applyFilters === "function") {
        applyFilters(); 
    }

    // 3. Re-render the big Preview Stage in the new language
    if (currentStory && typeof updatePreview === "function") {
        updatePreview(currentStory);
    }
    
    // (If you have VKids or FAQ, call their render functions here too)
    if (typeof renderVKids === "function") renderVKids(lang);
    if (typeof renderVFAQs === "function") renderVFAQs(lang);

    // 4. Handle RTL/LTR for Arabic
    document.documentElement.dir = (lang === 'ar') ? 'rtl' : 'ltr';

    // 5. Re-render dynamic components
    if (typeof renderVKids === "function") renderVKids(lang);
    if (typeof renderVFAQs === "function") renderVFAQs(lang);

    applyFilters(); 
    
    // Update the main stage if something is currently selected
    if (currentStory) {
        const btn = document.getElementById('mainActionButton');
        const key = (currentStory.type === 'video') ? "stories.play_btn" : "stories.read_btn";
        btn.innerText = translations[lang][key];
    }

    const confessionSection = document.getElementById('v-kids-confessions');
    if (confessionSection) {
        // 1. Detect if it's a mobile screen (under 768px)
        const isMobile = window.innerWidth <= 768;

        // 2. The 12-Image Map (Update filenames to match your assets)
        const bgMap = {
            'en': { web: 'form-bg.jpg', mob: 'form-bg-en-mobile.jpg' },
            'ar': { web: 'form-bg-ar.jpg', mob: 'form-bg-ar-mobile.jpg' },
            'id': { web: 'form-bg-id.jpg', mob: 'form-bg-id-mobile.jpg' },
            'fr': { web: 'form-bg-fr.jpg', mob: 'form-bg-fr-mobile.jpg' },
            'ru': { web: 'form-bg-ru.jpg', mob: 'form-bg-ru-mobile.jpg' },
            'tr': { web: 'form-bg-tr.jpg', mob: 'form-bg-tr-mobile.jpg' }
        };

        // 3. Get the specific image
        const selectedBgs = bgMap[lang] || bgMap['en']; // Fallback to English
        const finalImage = isMobile ? selectedBgs.mob : selectedBgs.web;

        // 4. Apply the background
        confessionSection.style.backgroundImage = `url('assets/images/${finalImage}')`;
    }

    window.addEventListener('resize', () => {
    const currentLang = localStorage.getItem('selectedLanguage') || 'en';
    changeLanguage(currentLang);
});

}

